function pathwayId(){try{return service&&service.getPathway?service.getPathway():null}catch{return null}}
function pathwayName(){const p=pathwayId();return p&&service.names&&service.names[p]||null}
function lockLegacyMenus(){if(!service)return;let anchor=null;for(const id of ['operation','range']){const control=document.getElementById(id);if(!control)continue;control.disabled=true;const box=control.closest?.('label')||control;box.hidden=true;anchor=anchor||box}const name=pathwayName();if(!anchor||!name||!anchor.before)return;const tag=document.getElementById('practiceSkill')||document.createElement('span');tag.id='practiceSkill';tag.className='practiceSkill';tag.setAttribute('role','status');tag.textContent='Practicing: '+name;tag.style.cssText='display:inline-flex;align-items:center;align-self:center;justify-self:start;width:max-content;max-width:100%;box-sizing:border-box;padding:7px 13px;border:2px solid currentColor;border-radius:999px;font:800 15px system-ui;letter-spacing:.2px;white-space:nowrap';if(!tag.isConnected)anchor.before(tag)}
lockLegacyMenus();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',lockLegacyMenus);
window.ArcadeLearning={get active(){return!!service},get pathway(){return pathwayId()},get pathwayName(){return pathwayName()},begin,next,shown,record,stats:()=>service?.stats(),get limitMs(){return service?.limitMs||3000}};
